1	import { useState } from "react";
2	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
3	import { ApiError, api } from "../api/client";
4	import type { AvailabilityWindow, CrewProfile } from "../api/types";
5	import { useAuth } from "../auth/AuthContext";
6	import { ErrorBanner } from "../components/ErrorBanner";
7	import { Spinner } from "../components/Spinner";
8	import { formatDate, proficiencyLabel } from "../lib/format";
9	
10	function errorMessage(error: unknown, fallback: string): string {
11	  return error instanceof ApiError ? error.message : fallback;
12	}
13	
14	const PROFICIENCY_LEVELS = [1, 2, 3, 4, 5];
15	
16	interface ProfilePatchVars {
17	  name: string;
18	  contact: string;
19	  bio: string;
20	}
21	
22	interface SkillSetVars {
23	  skillId: number;
24	  skillName: string;
25	  proficiency: number;
26	}
27	
28	interface WindowAddVars {
29	  startDate: string;
30	  endDate: string;
31	}
32	
33	/** Crew Member self-service: view/edit own profile (FR-4), set skill
34	 * proficiency (FR-6), and manage unavailability windows (FR-7). The one
35	 * screen in this task with real forms/mutations — reuses the
36	 * optimistic-update/loading/error pattern from MissionDetailScreen rather
37	 * than inventing a new one. */
38	export function MyProfileScreen() {
39	  const { user } = useAuth();
40	  const userId = user!.id;
41	  const queryClient = useQueryClient();
42	
43	  const profileQuery = useQuery({ queryKey: ["crew", "profile", userId], queryFn: () => api.crew.profile(userId) });
44	  const skillsQuery = useQuery({ queryKey: ["skills"], queryFn: api.skills.list });
45	  const availabilityQuery = useQuery({
46	    queryKey: ["crew", "availability", userId],
47	    queryFn: () => api.crew.listAvailability(userId),
48	  });
49	
50	  const [isEditingProfile, setIsEditingProfile] = useState(false);
51	  const [nameField, setNameField] = useState("");
52	  const [contactField, setContactField] = useState("");
53	  const [bioField, setBioField] = useState("");
54	
55	  const [editingSkillId, setEditingSkillId] = useState<number | null>(null);
56	  const [editingProficiency, setEditingProficiency] = useState(3);
57	  const [newSkillId, setNewSkillId] = useState("");
58	  const [newProficiency, setNewProficiency] = useState(3);
59	
60	  const [windowStart, setWindowStart] = useState("");
61	  const [windowEnd, setWindowEnd] = useState("");
62	
63	  const profileMutation = useMutation({
64	    mutationFn: (vars: ProfilePatchVars) =>
65	      api.crew.updateProfile(userId, { name: vars.name, contact: vars.contact, bio: vars.bio }),
66	    onMutate: async (vars) => {
67	      await queryClient.cancelQueries({ queryKey: ["crew", "profile", userId] });
68	      const previous = queryClient.getQueryData<CrewProfile>(["crew", "profile", userId]);
69	      if (previous) {
70	        queryClient.setQueryData<CrewProfile>(["crew", "profile", userId], {
71	          ...previous,
72	          name: vars.name,
73	          contact: vars.contact,
74	          bio: vars.bio,
75	        });
76	      }
77	      return { previous };
78	    },
79	    onSuccess: () => setIsEditingProfile(false),
80	    onError: (_err, _vars, context) => {
81	      if (context?.previous) queryClient.setQueryData(["crew", "profile", userId], context.previous);
82	    },
83	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["crew", "profile", userId] }),
84	  });
85	
86	  const skillMutation = useMutation({
87	    mutationFn: (vars: SkillSetVars) => api.crew.setSkill(userId, vars.skillName, vars.proficiency),
88	    onMutate: async (vars) => {
89	      await queryClient.cancelQueries({ queryKey: ["crew", "profile", userId] });
90	      const previous = queryClient.getQueryData<CrewProfile>(["crew", "profile", userId]);
91	      if (previous) {
92	        const held = previous.skills.some((s) => s.skill_id === vars.skillId);
93	        const skills = held
94	          ? previous.skills.map((s) => (s.skill_id === vars.skillId ? { ...s, proficiency: vars.proficiency } : s))
95	          : [...previous.skills, { skill_id: vars.skillId, skill_name: vars.skillName, proficiency: vars.proficiency }];
96	        queryClient.setQueryData<CrewProfile>(["crew", "profile", userId], { ...previous, skills });
97	      }
98	      return { previous };
99	    },
100	    onSuccess: () => {
101	      setEditingSkillId(null);
102	      setNewSkillId("");
103	      setNewProficiency(3);
104	    },
105	    onError: (_err, _vars, context) => {
106	      if (context?.previous) queryClient.setQueryData(["crew", "profile", userId], context.previous);
107	    },
108	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["crew", "profile", userId] }),
109	  });
110	
111	  const addWindowMutation = useMutation({
112	    mutationFn: (vars: WindowAddVars) => api.crew.addAvailability(userId, vars.startDate, vars.endDate),
113	    onMutate: async (vars) => {
114	      await queryClient.cancelQueries({ queryKey: ["crew", "availability", userId] });
115	      const previous = queryClient.getQueryData<AvailabilityWindow[]>(["crew", "availability", userId]);
116	      const optimistic: AvailabilityWindow = {
117	        id: -Date.now(),
118	        crew_id: userId,
119	        start_date: vars.startDate,
120	        end_date: vars.endDate,
121	      };
122	      queryClient.setQueryData<AvailabilityWindow[]>(["crew", "availability", userId], (old) => [
123	        ...(old ?? []),
124	        optimistic,
125	      ]);
126	      return { previous };
127	    },
128	    onSuccess: () => {
129	      setWindowStart("");
130	      setWindowEnd("");
131	    },
132	    onError: (_err, _vars, context) => {
133	      if (context?.previous) queryClient.setQueryData(["crew", "availability", userId], context.previous);
134	    },
135	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["crew", "availability", userId] }),
136	  });
137	
138	  const removeWindowMutation = useMutation({
139	    mutationFn: (windowId: number) => api.crew.removeAvailability(userId, windowId),
140	    onMutate: async (windowId) => {
141	      await queryClient.cancelQueries({ queryKey: ["crew", "availability", userId] });
142	      const previous = queryClient.getQueryData<AvailabilityWindow[]>(["crew", "availability", userId]);
143	      queryClient.setQueryData<AvailabilityWindow[]>(["crew", "availability", userId], (old) =>
144	        (old ?? []).filter((w) => w.id !== windowId),
145	      );
146	      return { previous };
147	    },
148	    onError: (_err, _vars, context) => {
149	      if (context?.previous) queryClient.setQueryData(["crew", "availability", userId], context.previous);
150	    },
151	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["crew", "availability", userId] }),
152	  });
153	
154	  if (profileQuery.isPending) {
155	    return (
156	      <div className="flex flex-1 items-center justify-center px-10 py-8">
157	        <Spinner className="h-6 w-6 text-text-3" />
158	      </div>
159	    );
160	  }
161	
162	  if (profileQuery.isError) {
163	    return (
164	      <div className="flex flex-1 flex-col gap-4 px-10 py-8">
165	        <ErrorBanner
166	          message={errorMessage(profileQuery.error, "Couldn't load your profile.")}
167	          onRetry={() => profileQuery.refetch()}
168	        />
169	      </div>
170	    );
171	  }
172	
173	  const profile = profileQuery.data;
174	  const skills = skillsQuery.data ?? [];
175	  const heldSkillIds = new Set(profile.skills.map((s) => s.skill_id));
176	  const availableToAdd = skills.filter((s) => !heldSkillIds.has(s.id));
177	  const windows = [...(availabilityQuery.data ?? [])].sort((a, b) => a.start_date.localeCompare(b.start_date));
178	
179	  return (
180	    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-7">
181	      <div>
182	        <div className="text-[22px] font-bold">My Profile</div>
183	        <div className="mt-0.5 text-[13px] text-text-2">Your profile, skills, and availability.</div>
184	      </div>
185	
186	      <div className="flex items-start gap-7">
187	        {/* Left column */}
188	        <div className="flex min-w-0 flex-1 flex-col gap-5">
189	          {/* Profile details */}
190	          <div className="rounded-[10px] border border-border bg-surface p-5">
191	            <div className="mb-4 flex items-center justify-between">
192	              <div className="text-[15px] font-bold">Profile</div>
193	              {!isEditingProfile && (
194	                <button
195	                  type="button"
196	                  onClick={() => {
197	                    setNameField(profile.name);
198	                    setContactField(profile.contact ?? "");
199	                    setBioField(profile.bio ?? "");
200	                    setIsEditingProfile(true);
201	                  }}
202	                  className="text-[12.5px] font-semibold text-accent hover:text-accent-dark"
203	                >
204	                  Edit
205	                </button>
206	              )}
207	            </div>
208	
209	            {!isEditingProfile ? (
210	              <div className="flex flex-col gap-3 text-sm">
211	                <Field label="Name" value={profile.name} />
212	                <Field label="Email" value={profile.email} />
213	                <Field label="Contact" value={profile.contact} placeholder="No contact info provided." />
214	                <Field label="Bio" value={profile.bio} placeholder="No bio provided." />
215	              </div>
216	            ) : (
217	              <form
218	                className="flex flex-col gap-3"
219	                onSubmit={(e) => {
220	                  e.preventDefault();
221	                  profileMutation.mutate({ name: nameField, contact: contactField, bio: bioField });
222	                }}
223	              >
224	                <div className="flex flex-col gap-1.5">
225	                  <label htmlFor="profile-name" className="text-xs font-semibold text-text-2">
226	                    Name
227	                  </label>
228	                  <input
229	                    id="profile-name"
230	                    type="text"
231	                    value={nameField}
232	                    onChange={(e) => setNameField(e.target.value)}
233	                    className="w-full rounded-md border border-border bg-surface px-3 py-2 text-[13px] focus:border-accent focus:outline-none"
234	                  />
235	                </div>
236	                <div className="flex flex-col gap-1.5">
237	                  <label htmlFor="profile-contact" className="text-xs font-semibold text-text-2">
238	                    Contact
239	                  </label>
240	                  <input
241	                    id="profile-contact"
242	                    type="text"
243	                    value={contactField}
244	                    onChange={(e) => setContactField(e.target.value)}
245	                    placeholder="Phone, alternate email, etc."
246	                    className="w-full rounded-md border border-border bg-surface px-3 py-2 text-[13px] focus:border-accent focus:outline-none"
247	                  />
248	                </div>
249	                <div className="flex flex-col gap-1.5">
250	                  <label htmlFor="profile-bio" className="text-xs font-semibold text-text-2">
251	                    Bio
252	                  </label>
253	                  <textarea
254	                    id="profile-bio"
255	                    value={bioField}
256	                    onChange={(e) => setBioField(e.target.value)}
257	                    rows={3}
258	                    className="w-full rounded-md border border-border bg-surface p-2 text-[13px] focus:border-accent focus:outline-none"
259	                  />
260	                </div>
261	                <div className="flex gap-2">
262	                  <button
263	                    type="submit"
264	                    disabled={profileMutation.isPending || nameField.trim().length === 0}
265	                    className="flex items-center justify-center gap-2 rounded-md bg-accent px-4 py-2 text-[13px] font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60"
266	                  >
267	                    {profileMutation.isPending && <Spinner />}
268	                    Save
269	                  </button>
270	                  <button
271	                    type="button"
272	                    onClick={() => setIsEditingProfile(false)}
273	                    className="rounded-md border border-border px-4 py-2 text-[13px] font-semibold text-text-2"
274	                  >
275	                    Cancel
276	                  </button>
277	                </div>
278	                {profileMutation.isError && (
279	                  <ErrorBanner message={errorMessage(profileMutation.error, "Couldn't save your profile.")} />
280	                )}
281	              </form>
282	            )}
283	          </div>
284	
285	          {/* Skills */}
286	          <div className="rounded-[10px] border border-border bg-surface p-5">
287	            <div className="mb-4 text-[15px] font-bold">Skills</div>
288	
289	            {profile.skills.length === 0 ? (
290	              <div className="mb-4 text-sm text-text-3">You haven't set any skill proficiencies yet.</div>
291	            ) : (
292	              <div className="mb-4 flex flex-col gap-2.5">
293	                {profile.skills.map((skill) => {
294	                  const isEditingRow = editingSkillId === skill.skill_id;
295	                  const isThisRow = skillMutation.variables?.skillId === skill.skill_id;
296	                  const isPending = skillMutation.isPending && isThisRow;
297	                  const isError = skillMutation.isError && isThisRow;
298	
299	                  return (
300	                    <div key={skill.skill_id} className="rounded-lg bg-surface-2 px-3.5 py-3">
301	                      <div className="flex items-center justify-between">
302	                        <div className="text-[13.5px] font-semibold">{skill.skill_name}</div>
303	
304	                        {!isEditingRow && (
305	                          <div className="flex items-center gap-3">
306	                            <div className="text-xs text-text-2">
307	                              {proficiencyLabel(skill.proficiency)}{" "}
308	                              <span className="font-mono text-text-3">({skill.proficiency}/5)</span>
309	                            </div>
310	                            <button
311	                              type="button"
312	                              onClick={() => {
313	                                setEditingSkillId(skill.skill_id);
314	                                setEditingProficiency(skill.proficiency);
315	                              }}
316	                              className="text-[12px] font-semibold text-accent hover:text-accent-dark"
317	                            >
318	                              Change
319	                            </button>
320	                          </div>
321	                        )}
322	                      </div>
323	
324	                      {isEditingRow && (
325	                        <div className="mt-2.5 flex items-center gap-2">
326	                          <select
327	                            aria-label={`Proficiency for ${skill.skill_name}`}
328	                            value={editingProficiency}
329	                            onChange={(e) => setEditingProficiency(Number(e.target.value))}
330	                            className="rounded-md border border-border bg-surface px-2.5 py-1.5 text-xs focus:border-accent focus:outline-none"
331	                          >
332	                            {PROFICIENCY_LEVELS.map((level) => (
333	                              <option key={level} value={level}>
334	                                {level} — {proficiencyLabel(level)}
335	                              </option>
336	                            ))}
337	                          </select>
338	                          <button
339	                            type="button"
340	                            disabled={isPending}
341	                            onClick={() =>
342	                              skillMutation.mutate({
343	                                skillId: skill.skill_id,
344	                                skillName: skill.skill_name,
345	                                proficiency: editingProficiency,
346	                              })
347	                            }
348	                            className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-semibold text-white disabled:opacity-60"
349	                          >
350	                            {isPending && <Spinner />}
351	                            Save
352	                          </button>
353	                          <button
354	                            type="button"
355	                            onClick={() => setEditingSkillId(null)}
356	                            className="rounded-md border border-border px-3 py-1.5 text-xs font-semibold text-text-2"
357	                          >
358	                            Cancel
359	                          </button>
360	                        </div>
361	                      )}
362	
363	                      {isError && (
364	                        <div className="mt-2">
365	                          <ErrorBanner message={errorMessage(skillMutation.error, "Couldn't update this skill.")} />
366	                        </div>
367	                      )}
368	                    </div>
369	                  );
370	                })}
371	              </div>
372	            )}
373	
374	            {availableToAdd.length > 0 && (
375	              <form
376	                className="flex flex-wrap items-end gap-2 border-t border-border pt-4"
377	                onSubmit={(e) => {
378	                  e.preventDefault();
379	                  if (!newSkillId) return;
380	                  const skill = skills.find((s) => s.id === Number(newSkillId));
381	                  if (!skill) return;
382	                  skillMutation.mutate({ skillId: skill.id, skillName: skill.name, proficiency: newProficiency });
383	                }}
384	              >
385	                <div className="flex flex-col gap-1.5">
386	                  <label htmlFor="new-skill" className="text-xs font-semibold text-text-2">
387	                    Add a skill
388	                  </label>
389	                  <select
390	                    id="new-skill"
391	                    value={newSkillId}
392	                    onChange={(e) => setNewSkillId(e.target.value)}
393	                    className="rounded-md border border-border bg-surface px-2.5 py-2 text-[13px] focus:border-accent focus:outline-none"
394	                  >
395	                    <option value="">Choose a skill…</option>
396	                    {availableToAdd.map((skill) => (
397	                      <option key={skill.id} value={skill.id}>
398	                        {skill.name}
399	                      </option>
400	                    ))}
401	                  </select>
402	                </div>
403	                <div className="flex flex-col gap-1.5">
